const items = $input.all();
const offres = [];

for (const item of items) {
  const resultats = item.json.resultats || [];

  for (const offre of resultats) {
    offres.push({
      json: {
        id_offre: offre.id,
        titre: offre.intitule,
        description: offre.description,
        url: offre.origineOffre?.urlOrigine || null,
        entreprise: offre.entreprise?.nom || null,
        localisation: offre.lieuTravail?.libelle || null,
        date_publication: offre.dateCreation,
        source: "France Travail",
        contrat: offre.typeContratLibelle || null,
        salaire: offre.salaire?.libelle || null
      }
    });
  }
}

return offres;

const items = $input.all();
const offres = [];

for (const item of items) {
  const resultats = item.json.data || [];

  for (const offre of resultats) {
    offres.push({
      json: {
        id_offre: offre.job_id,
        titre: offre.job_title,
        description: offre.job_description,
        url: offre.job_apply_link || offre.job_google_link || null,
        entreprise: offre.employer_name || null,
        entreprise_site_web: offre.employer_website || null,
        localisation: offre.job_city || offre.job_location || null,
        date_publication: offre.job_posted_at_datetime_utc || null,
        source: offre.job_publisher.toLowerCase() || "JSearch",
        contrat: offre.job_employment_type || null,
        salaire: offre.job_salary_string || null,
        remote: offre.job_is_remote || false
      }
    });
  }
}

return offres;

const items = $input.all();

const competences = items[0].json.data.map(comp => {
  return {
    json: {
      type_competence: comp.type_competence,
      title: comp.title,
      note: comp.note
    }
  };
});

return competences;

const items = $input.all();

const competences_texte = items.map(c => 
  `- ${c.json.title} (${c.json.type_competence}) : note ${c.json.note}/3`
).join('\n');

return [{ 
  json: { 
    competences_texte: competences_texte 
  } 
}];

const text = $input.first().json.text;
const offre = $('Boucle des offres').first().json;

// Nettoyer au cas où il y a des backticks
const cleaned = text
  .replace(/```json/g, '')
  .replace(/```/g, '')
  .trim();

const parsed = JSON.parse(cleaned);

return [{
  json: {
    id_offre: offre.id_offre || "",
    titre: offre.titre || "Non renseigné",
    entreprise: offre.entreprise || "Non renseigné",
    localisation: offre.localisation || "Non renseigné",
    contrat: offre.contrat || "Non renseigné",
    salaire: offre.salaire || "Non renseigné",
    source: offre.source || "Non renseigné",
    url: offre.url || "",
    score: parsed.score || 0,
    correspond: parsed.correspond || false,
    competences_matchees: JSON.stringify(parsed.competences_matchees) || "",
    competences_manquantes: JSON.stringify(parsed.competences_manquantes) || "",
    competences_a_ameliorer: JSON.stringify(parsed.competences_a_ameliorer) || "",
    raison: parsed.raison || "",
    conseils: parsed.conseils || "",
    type_offre: parsed.type_offre
  }
}];

